// ------------------------------------------------------------------------------- storage
static const char* PART_LABEL = "storage";

static esp_vfs_fat_mount_config_t mount_config(void)
{
    esp_vfs_fat_mount_config_t cfg = {};
    cfg.format_if_mount_failed = false;                  // never format as a side effect
    cfg.max_files = 4;
    cfg.allocation_unit_size = 4096;
    return cfg;
}
static wl_handle_t s_wl = WL_INVALID_HANDLE;

// True if the partition is still erased flash (all 0xFF) at both ends, where the file system
// (start) and the wear-levelling state (end) would be: a new or fully erased device.
static bool partition_blank(void)
{
    const esp_partition_t* part = esp_partition_find_first(ESP_PARTITION_TYPE_DATA,
                                                           ESP_PARTITION_SUBTYPE_DATA_FAT, PART_LABEL);
    if (!part) return false;
    static uint32_t buf[1024];                           // 4 KB
    const size_t chunk = sizeof(buf), span = 4 * chunk;  // check 16 KB at each end
    const size_t bases[2] = {0, part->size - span};
    for (size_t base : bases) {
        for (size_t off = 0; off < span; off += chunk) {
            if (esp_partition_read(part, base + off, buf, chunk) != ESP_OK) return false;
            for (uint32_t w : buf) if (w != 0xFFFFFFFFu) return false;
        }
    }
    return true;
}

// Mount without formatting; retry once (a passing fault then costs nothing). If it still
// fails, format only a blank partition. esp_vfs_fat_spiflash_format_rw_wl() returns ESP_OK
// only after the partition has really been formatted, so STORAGE_RESET means just that.
StorageState storage_init(void)
{
    esp_vfs_fat_mount_config_t cfg = mount_config();
    esp_err_t err = ESP_FAIL;
    for (int attempt = 0; attempt < 2 && err != ESP_OK; attempt++)
        err = esp_vfs_fat_spiflash_mount_rw_wl(DATA_DIR, PART_LABEL, &cfg, &s_wl);
    if (err == ESP_OK) return STORAGE_OK;

    if (!partition_blank()) {
        ESP_LOGE(TAG, "FAT mount failed (%s) and the partition holds data: not formatting", esp_err_to_name(err));
        return STORAGE_DAMAGED;
    }
    ESP_LOGW(TAG, "storage partition is blank: formatting");
    return storage_erase() ? STORAGE_RESET : STORAGE_FAILED;
}

bool storage_erase(void)
{
    esp_err_t err = esp_vfs_fat_spiflash_format_rw_wl(DATA_DIR, PART_LABEL);
    if (err != ESP_OK) { ESP_LOGE(TAG, "format failed: %s", esp_err_to_name(err)); return false; }
    esp_vfs_fat_mount_config_t cfg = mount_config();
    err = esp_vfs_fat_spiflash_mount_rw_wl(DATA_DIR, PART_LABEL, &cfg, &s_wl);
    if (err != ESP_OK) { ESP_LOGE(TAG, "mount after format failed: %s", esp_err_to_name(err)); return false; }
    return true;
}

// Only finished recordings, named exactly RUNnn.CSV, may be listed, downloaded or deleted.
// This hides temporary RUNnn.TMP files and blocks paths such as "../x" or "a/b".
bool is_run_name(const char* f)
{
    return strlen(f) == 9 && strncmp(f, "RUN", 3) == 0 && isdigit((unsigned char)f[3])
        && isdigit((unsigned char)f[4]) && strcmp(f + 5, ".CSV") == 0;
}

// Read and validate the ?f=NAME query parameter.
static bool query_file(httpd_req_t* req, char* name, size_t n)
{
    char q[64];
    return httpd_req_get_url_query_str(req, q, sizeof(q)) == ESP_OK
        && httpd_query_key_value(q, "f", name, n) == ESP_OK
        && is_run_name(name);
}

// ------------------------------------------------------------------------------- HTTP handlers
static esp_err_t h_index(httpd_req_t* req)
{
    httpd_resp_set_type(req, "text/html; charset=utf-8");
    return httpd_resp_send(req, page_data(), page_size());
}

static esp_err_t h_files(httpd_req_t* req)
{
    httpd_resp_set_type(req, "application/json");
    httpd_resp_sendstr_chunk(req, "[");
    DIR* d = opendir(DATA_DIR);
    bool first = true;
    if (d) {
        struct dirent* e;
        while ((e = readdir(d))) {
            if (!is_run_name(e->d_name)) continue;       // finished recordings only
            char path[300];
            struct stat st;
            snprintf(path, sizeof(path), "%s/%s", DATA_DIR, e->d_name);
            if (stat(path, &st) != 0 || !S_ISREG(st.st_mode)) continue;
            char item[320];
            snprintf(item, sizeof(item), "%s{\"name\":\"%s\",\"size\":%ld}", first ? "" : ",",
                     e->d_name, (long)st.st_size);
            httpd_resp_sendstr_chunk(req, item);
            first = false;
        }
        closedir(d);
    }
    httpd_resp_sendstr_chunk(req, "]");
    return httpd_resp_sendstr_chunk(req, nullptr);       // end of chunked response
}

static esp_err_t h_download(httpd_req_t* req)
{
    char name[16], path[40];
    if (!query_file(req, name, sizeof(name))) return httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "bad name");
    snprintf(path, sizeof(path), "%s/%s", DATA_DIR, name);
    FILE* f = fopen(path, "r");
    if (!f) return httpd_resp_send_err(req, HTTPD_404_NOT_FOUND, "not found");

    char disp[64];
    snprintf(disp, sizeof(disp), "attachment; filename=\"%s\"", name);
    httpd_resp_set_type(req, "text/csv");
    httpd_resp_set_hdr(req, "Content-Disposition", disp);
    // Static buffer: handlers run one at a time on the single HTTP server task.
    static char buf[2048];
    size_t n;
    while ((n = fread(buf, 1, sizeof(buf), f)) > 0) {
        if (httpd_resp_send_chunk(req, buf, n) != ESP_OK) break;
    }
    fclose(f);
    return httpd_resp_send_chunk(req, nullptr, 0);
}

// Deleting needs confirmation on the StickS3 (KEY1): reply at once with the request number;
// the page then follows del_seq / del_state in the status line.
static esp_err_t h_delete(httpd_req_t* req)
{
    char name[16], reply[24];
    if (!query_file(req, name, sizeof(name))) return httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "bad name");
    const int seq = request_delete(name);
    if (!seq) return httpd_resp_send_err(req, HTTPD_500_INTERNAL_SERVER_ERROR, "busy");
    snprintf(reply, sizeof(reply), "pending,%d", seq);
    return httpd_resp_sendstr(req, reply);
}

// WebSocket endpoint. The handshake (GET) needs no work; clients are found later with
// httpd_get_client_list(). Anything a browser sends is read and discarded.
static esp_err_t h_ws(httpd_req_t* req)
{
    if (req->method == HTTP_GET) return ESP_OK;
    httpd_ws_frame_t frame = {};
    frame.type = HTTPD_WS_TYPE_TEXT;
    if (httpd_ws_recv_frame(req, &frame, 0) != ESP_OK) return ESP_FAIL;   // length only
    if (frame.len) {
        static uint8_t junk[128];
        frame.payload = junk;
        httpd_ws_recv_frame(req, &frame, frame.len < sizeof(junk) ? frame.len : sizeof(junk));
    }
    return ESP_OK;
}

// ------------------------------------------------------------------------------- live stream
// One text message, allocated by live_task and freed by send_batch.
struct Batch { size_t len; char text[1]; };

// Runs on the HTTP server task (queued with httpd_queue_work): send one batch to every
// WebSocket client, and count them for the screen.
static void send_batch(void* arg)
{
    Batch* b = (Batch*)arg;
    size_t fds_n = 8;
    int fds[8];
    int count = 0;
    if (httpd_get_client_list(s_server, &fds_n, fds) == ESP_OK) {
        for (size_t i = 0; i < fds_n; i++) {
            if (httpd_ws_get_fd_info(s_server, fds[i]) != HTTPD_WS_CLIENT_WEBSOCKET) continue;
            count++;
            httpd_ws_frame_t frame = {};
            frame.type = HTTPD_WS_TYPE_TEXT;
            frame.payload = (uint8_t*)b->text;
            frame.len = b->len;
            frame.final = true;
            httpd_ws_send_frame_async(s_server, fds[i], &frame);
        }
    }
    s_ws_clients = count;
    free(b);
    s_pending--;                                         // this batch is no longer pending
}

// Live stream, shared format for Wi-Fi (this file) and USB (usb.cpp).
//
// Every 100 ms one message: a status line, then the samples since the previous message,
// thinned to LIVE_HZ (every 4th sample, chosen by its sample number so Wi-Fi and USB agree).
// Recordings always keep the full SAMPLE_HZ. Fewer, smaller messages leave more airtime
// when many StickS3s share a room.
//
// Status line (lets the browser follow the device and draw angles and orientation):
//   #S,page,zero,rec_on,rec_n,rec_target,dur_s,last_rows,last_file,
//      bias_x,bias_y,bias_z,theta_x,theta_y,theta_z,q_w,q_x,q_y,q_z,stale,acc200,fused,
//      bat_pct,bat_mv,charging,del_seq,del_state,del_name
//   page 0..3 = Accel, Gyro, Orient, Record; zero 0 busy / 1 done / 2 moved;
//   bias in deg/s, theta in degrees, q = the Orient page's quaternion: fused (roll/pitch
//   relative to gravity, yaw relative to zeroing) when fused = 1, gyro-only when fused = 0;
//   stale = polls since boot without new accelerometer data;
//   acc200 = 1 if the accelerometer was confirmed at 200 Hz, 0 if it stayed at 100 Hz;
//   bat_pct 0-100 (-1 unknown, smoothed), bat_mv in millivolts, charging 0/1 (USB power present);
//   del_seq / del_state / del_name: the latest delete request and its state (see app.h).
// Sample lines:
//   t_ms,ax,ay,az,wx,wy,wz   (ms since boot, g, deg/s; gyro offset not removed)
// Over USB the same lines start with "@S," and "@L," instead, and every sample is sent
// (100 Hz; see usb.cpp).
//
// Back-pressure (Wi-Fi): sending runs on the server task and can block (slow or sleeping
// client, a download in progress). At most MAX_PENDING messages may wait; while that many
// are pending, new samples are dropped from the stream (never from recordings).
static constexpr size_t STATUS_MAX = 320;
static constexpr size_t SAMPLE_MAX = 64;
static constexpr int    LIVE_STEP  = SAMPLE_HZ / LIVE_HZ;  // 4: keep every 4th sample

int status_fields(char* buf, size_t n)
{
    char last_file[16] = "";
    if (ui_last_run > 0) snprintf(last_file, sizeof(last_file), "RUN%02d.CSV", ui_last_run.load());
    ImuView v;
    imu_view(&v);
    const bool fused = ui_orient_fused;
    const float* qo = fused ? v.qf : v.q;                    // what the Orient page shows
    int del_seq, del_state;
    char del_name[16];
    delete_status(&del_seq, &del_state, del_name, sizeof(del_name));
    const int len = snprintf(buf, n,
        "%d,%d,%d,%d,%d,%d,%d,%s,%.3f,%.3f,%.3f,%.2f,%.2f,%.2f,%.5f,%.5f,%.5f,%.5f,%lu,%d,%d,%d,%d,%d,%d,%d,%s",
        ui_page.load(), imu_zero_result(), imu_rec_running() ? 1 : 0, imu_rec_count(),
        imu_rec_target(), ui_dur_s.load(), ui_last_rows.load(), last_file,
        v.bias[0], v.bias[1], v.bias[2], v.theta[0], v.theta[1], v.theta[2],
        qo[0], qo[1], qo[2], qo[3], (unsigned long)imu_stale_reads(), imu_accel_200hz() ? 1 : 0,
        fused ? 1 : 0, imu_battery_percent(), imu_battery_mv(), imu_battery_charging() ? 1 : 0,
        del_seq, del_state, del_name);
    return (len < 0 || len >= (int)n) ? 0 : len;
}

int sample_line(char* buf, size_t n, const Sample& s)
{
    const int len = snprintf(buf, n, "%lu,%.3f,%.3f,%.3f,%.1f,%.1f,%.1f\n",
                             (unsigned long)s.t_ms, s.ax, s.ay, s.az, s.wx, s.wy, s.wz);
    return (len < 0 || len >= (int)n) ? 0 : len;
}

static void live_task(void*)
{
    uint32_t tail = live_head;                           // next sample to consider
    while (true) {
        vTaskDelay(pdMS_TO_TICKS(100));                  // 10 messages per second
        const uint32_t head = live_head;
        // If this task fell behind, skip the oldest samples rather than read slots
        // the IMU task may be overwriting (keep a safety margin of 8).
        if (head - tail > LIVE_N - 8) tail = head - (LIVE_N - 8);
        if (s_pending >= MAX_PENDING) { tail = head; continue; }   // drop: sender is behind
        const uint32_t n = (head - tail) / LIVE_STEP + 1;

        Batch* b = (Batch*)malloc(sizeof(Batch) + STATUS_MAX + n * SAMPLE_MAX);
        if (!b) continue;
        int len = 0;
        const int st = status_fields(b->text + 3, STATUS_MAX - 4);
        if (st > 0) { memcpy(b->text, "#S,", 3); len = 3 + st; b->text[len++] = '\n'; }
        for (; tail != head; tail++) {
            if (tail % LIVE_STEP) continue;              // thin to LIVE_HZ
            len += sample_line(b->text + len, SAMPLE_MAX, live_ring[tail % LIVE_N]);
        }
        b->len = len;
        s_pending++;
        if (httpd_queue_work(s_server, send_batch, b) != ESP_OK) { free(b); s_pending--; }
    }
}

// ------------------------------------------------------------------------------- Wi-Fi + server
bool net_start(void)
{
    if (s_server) return true;

    // NVS is required by the Wi-Fi driver for calibration data.
    esp_err_t err = nvs_flash_init();
    if (err == ESP_ERR_NVS_NO_FREE_PAGES || err == ESP_ERR_NVS_NEW_VERSION_FOUND) {
        nvs_flash_erase();
        nvs_flash_init();
    }
    esp_netif_init();
    esp_event_loop_create_default();
    esp_netif_create_default_wifi_ap();                  // DHCP server, 192.168.4.1

    wifi_init_config_t wcfg = WIFI_INIT_CONFIG_DEFAULT();
    if ((err = esp_wifi_init(&wcfg)) != ESP_OK) { ESP_LOGE(TAG, "wifi init: %s", esp_err_to_name(err)); return false; }

    // A name per device, so students join their own StickS3. Taken from the chip's factory
    // MAC address, which (unlike the soft-AP MAC) is the same in ESP-IDF and Arduino builds,
    // so a StickS3 keeps its name whichever version is flashed.
    uint8_t mac[6];
    esp_efuse_mac_get_default(mac);
    char ssid[16];
    snprintf(ssid, sizeof(ssid), "IMU-%02X%02X%02X", mac[3], mac[4], mac[5]);

    // Spread devices over channels 1, 6 and 11 (the 2.4 GHz channels that do not overlap).
    // Fibonacci hashing (multiply by 2^32 / golden ratio, keep the top bits) splits evenly
    // spaced MAC addresses, as in a batch of devices, about equally over the three channels.
    // Phones and laptops find the channel by themselves.
    static const uint8_t CHANNELS[3] = {1, 6, 11};
    const uint32_t id = ((uint32_t)mac[3] << 16) | ((uint32_t)mac[4] << 8) | mac[5];
    const uint32_t h = id * 2654435761u;
    const int channel = CHANNELS[((uint64_t)h * 3) >> 32];

    wifi_config_t ap = {};
    strcpy((char*)ap.ap.ssid, ssid);
    ap.ap.ssid_len = strlen(ssid);
    ap.ap.channel = channel;
    ap.ap.max_connection = 4;
    ap.ap.authmode = WIFI_AUTH_OPEN;                     // no password; set WIFI_AUTH_WPA2_PSK + ap.ap.password to add one
    // Beacons every 200 TU (~205 ms) instead of 100: half the beacon airtime per device.
    ap.ap.beacon_interval = BEACON_TU;
    if ((err = esp_wifi_set_mode(WIFI_MODE_AP)) != ESP_OK
        || (err = esp_wifi_set_config(WIFI_IF_AP, &ap)) != ESP_OK
        // Disable the 802.11b rates (1-11 Mbps): beacons and broadcasts then go at 6 Mbps
        // instead of 1 Mbps, about 6 times less airtime each. (The protocol set itself must
        // still include 802.11b on the ESP32, so the rates are switched off instead.)
        // Every phone and laptop made since about 2005 supports the faster 802.11g rates.
        || (err = esp_wifi_config_11b_rate(WIFI_IF_AP, true)) != ESP_OK
        || (err = esp_wifi_start()) != ESP_OK) {
        ESP_LOGE(TAG, "wifi start: %s", esp_err_to_name(err));
        return false;
    }
    // Use a 20 MHz channel. A 40 MHz channel would cover two of the three non-overlapping
    // channels and undo the spreading above; a logger needs far less than 20 MHz of capacity.
    wifi_bandwidth_t bw_default = WIFI_BW20, bw = WIFI_BW20;
    esp_wifi_get_bandwidth(WIFI_IF_AP, &bw_default);
    if ((err = esp_wifi_set_bandwidth(WIFI_IF_AP, WIFI_BW20)) != ESP_OK)
        ESP_LOGW(TAG, "set 20 MHz: %s", esp_err_to_name(err));
    esp_wifi_get_bandwidth(WIFI_IF_AP, &bw);
    printf("# wifi bandwidth: default %d MHz, now %d MHz\n", bw_default == WIFI_BW40 ? 40 : 20, bw == WIFI_BW40 ? 40 : 20);

    // Lower transmit power: a student's phone is within a few metres, and a weaker signal
    // means devices across the room interfere less with each other (better reuse of the
    // three channels).
    if ((err = esp_wifi_set_max_tx_power(TX_POWER_QDBM)) != ESP_OK)
        ESP_LOGW(TAG, "tx power: %s", esp_err_to_name(err));
    int8_t txp = 0;
    esp_wifi_get_max_tx_power(&txp);
    printf("# wifi 802.11b rates off, beacon %d TU, tx power %.1f dBm\n", BEACON_TU, txp / 4.0);

    strcpy(s_ssid, ssid);                                // hotspot is visible from here on
    s_channel = channel;

    httpd_config_t hc = HTTPD_DEFAULT_CONFIG();
    hc.lru_purge_enable = true;                          // drop the oldest connection when full
    hc.max_open_sockets = 7;
    hc.send_wait_timeout = 1;                            // s; default 5 lets one stalled client block sending
    if (httpd_start(&s_server, &hc) != ESP_OK) { s_server = nullptr; ESP_LOGE(TAG, "http server failed"); return false; }

    struct Route { const char* uri; httpd_method_t method; esp_err_t (*handler)(httpd_req_t*); };
    static const Route routes[] = {
        {"/",          HTTP_GET,  h_index},
        {"/api/files", HTTP_GET,  h_files},
        {"/dl",        HTTP_GET,  h_download},
        {"/del",       HTTP_POST, h_delete},
    };
    for (const auto& r : routes) {
        httpd_uri_t u = {};
        u.uri = r.uri;
        u.method = r.method;
        u.handler = r.handler;
        httpd_register_uri_handler(s_server, &u);
    }
    httpd_uri_t ws = {};
    ws.uri = "/ws";
    ws.method = HTTP_GET;
    ws.handler = h_ws;
    ws.is_websocket = true;
    httpd_register_uri_handler(s_server, &ws);

    // Core 0 with Wi-Fi; priority below the IMU task.
    if (xTaskCreatePinnedToCore(live_task, "live", 4096, nullptr, 5, nullptr, 0) != pdPASS) {
        ESP_LOGE(TAG, "live task failed");
        return false;
    }
    s_web_ok = true;
    // printf rather than ESP_LOGI: the Arduino core hides ESP-IDF info logs.
    printf("# hotspot %s, channel %d, http://192.168.4.1\n", s_ssid, s_channel);
    return true;
}

const char* net_ssid(void)       { return s_ssid; }
bool        net_web_ok(void)     { return s_web_ok; }
int         net_channel(void)    { return s_channel; }
int         net_ws_clients(void) { return s_ws_clients; }
